<form method="POST" action="{{ route('password.update') }}" class="space-y-4">@csrf<input type="hidden" name="token" value="{{ $token }}"><label class="auth-label block text-xs font-semibold">Alamat email<input type="email" name="email" required value="{{ old('email', $request->email) }}" autocomplete="email" class="auth-input mt-1.5 w-full rounded-xl border px-3.5 py-2.5 text-sm"></label><label class="auth-label block text-xs font-semibold">Kata sandi baru<div class="relative mt-1.5"><input id="password" type="password" name="password" required minlength="12" maxlength="32" autocomplete="new-password" class="auth-input w-full rounded-xl border px-3.5 py-2.5 pr-12 text-sm"><button type="button" data-toggle-password="password" class="absolute right-3 top-1/2 -translate-y-1/2 text-stone-500" aria-label="Tampilkan kata sandi"><i data-lucide="eye" class="h-4 w-4"></i></button></div></label><div id="password-rules" class="rounded-xl bg-[#FAF8F1] p-3 text-xs dark:bg-[#24211B]"><div class="mb-2 flex items-center justify-between"><p class="auth-muted font-semibold">Ketentuan kata sandi</p><span id="password-strength" class="rounded-full bg-stone-200 px-2 py-1 text-[10px] font-bold text-stone-600 transition-colors dark:bg-stone-700 dark:text-stone-200">Belum diisi</span></div><div class="mb-3 h-1.5 overflow-hidden rounded-full bg-stone-200 dark:bg-stone-700"><div id="password-progress" class="h-full w-0 rounded-full bg-[#E09F09] transition-[width,background-color] duration-300 ease-out"></div></div><ul class="space-y-1.5 auth-muted"><li data-rule="length" class="password-rule">12–32 karakter</li><li data-rule="edges" class="password-rule">Tidak diawali atau diakhiri spasi</li><li data-rule="categories" class="password-rule">Memenuhi minimal 3 kategori karakter</li></ul><p class="auth-muted mt-2">Kategori: huruf besar, huruf kecil, angka, simbol.</p></div><label class="auth-label block text-xs font-semibold">Ulangi kata sandi<div class="relative mt-1.5"><input id="password-confirmation" type="password" name="password_confirmation" required autocomplete="new-password" class="auth-input mt-1.5 w-full rounded-xl border px-3.5 py-2.5 pr-12 text-sm"><button type="button" data-toggle-password="password-confirmation" class="absolute right-3 top-1/2 -translate-y-1/2 text-stone-500" aria-label="Tampilkan ulang kata sandi"><i data-lucide="eye" class="h-4 w-4"></i></button></div><span id="password-match" class="mt-1 hidden text-xs"></span></label><button class="w-full rounded-xl bg-[#E09F09] py-3 text-sm font-semibold text-[#1A1302] transition hover:bg-[#C78A05]">Simpan kata sandi baru</button></form>
<script>(function(){const input=document.getElementById('password'),confirmation=document.getElementById('password-confirmation'),bar=document.getElementById('password-progress'),badge=document.getElementById('password-strength'),match=document.getElementById('password-match');const rules={length:v=>v.length>=12&&v.length<=32,edges:v=>v.length>0&&!/^\s|\s$/.test(v),categories:v=>[/[A-Z]/.test(v),/[a-z]/.test(v),/[0-9]/.test(v),/[^A-Za-z0-9 ]/.test(v)].filter(Boolean).length>=3},labels={length:'12–32 karakter',edges:'Tidak diawali atau diakhiri spasi',categories:'Memenuhi minimal 3 kategori karakter'};function update(){const checks=Object.entries(rules).map(([k,fn])=>[k,fn(input.value)]),score=checks.filter(([,ok])=>ok).length;checks.forEach(([k,ok])=>{const el=document.querySelector('[data-rule="'+k+'"]');el.classList.toggle('is-valid',ok);el.classList.toggle('is-invalid',!!input.value&&!ok);el.innerHTML='<span class="rule-icon" aria-hidden="true">'+(ok?'✓':'○')+'</span><span>'+labels[k]+'</span>'});bar.style.width=(score/3*100)+'%';bar.style.backgroundColor=score===3?'#16803c':score===0?'#E09F09':'#d99b16';badge.textContent=!input.value?'Belum diisi':score===3?'Kuat':score===2?'Hampir kuat':'Perlu dilengkapi';match.classList.toggle('hidden',!confirmation.value);if(confirmation.value){const same=confirmation.value===input.value;match.textContent=same?'Kata sandi cocok':'Kata sandi belum cocok';match.className='mt-1 text-xs '+(same?'text-green-700':'text-amber-700')}}input.addEventListener('input',update);confirmation.addEventListener('input',update);document.querySelectorAll('[data-toggle-password]').forEach(b=>b.addEventListener('click',()=>{const el=document.getElementById(b.dataset.togglePassword);el.type=el.type==='password'?'text':'password';b.setAttribute('aria-label',el.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi')}));update()})();</script>
